201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
204	        HttpHeaders headers = new HttpHeaders();
205	        Visit visit = visitMapper.toVisit(visitFieldsDto);
206	        Pet pet = new Pet();
207	        pet.setId(petId);
208	        visit.setPet(pet);
209	        this.clinicService.saveVisit(visit);
210	        VisitDto visitDto = visitMapper.toVisitDto(visit);
211	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
212	            .buildAndExpand(visit.getId()).toUri());
213	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
214	    }
