8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
22	    @Mapping(target = "initials", expression = "java(initials(owner))")
23	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
24	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
25	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
26	    @Mapping(target = "locality", expression = "java(locality(owner))")
27	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    /**
31	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when an email address
32	     * is present (non-null and non-blank), otherwise {@code 'PHONE'}.
33	     */
34	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
35	        if (owner == null) {
36	            return null;
37	        }
38	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
39	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
40	    }
41	
42	    /**
43	     * Derives the owner's locality from its region (see {@link Owner#getRegion()}). Returns the
44	     * canonical region string, or {@code 'UNKNOWN'} when the owner has no known region.
45	     */
46	    default String locality(Owner owner) {
47	        if (owner == null) {
48	            return null;
49	        }
50	        String region = owner.getRegion();
51	        return region != null ? region : "UNKNOWN";
52	    }
53	
54	    /**
55	     * Returns the owner's numeric membership level, assigned on creation. The level starts at
56	     * {@code 1}, gains {@code 1} when an email is present, gains {@code 1} when the owner has no
57	     * namesakes (namesakeCount is 0), and is capped at {@code 3} (level 4 is reserved for tenure).
58	     */
59	    default Integer membershipLevel(Owner owner) {
60	        if (owner == null) {
61	            return null;
62	        }
63	        int level = 1;
64	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
65	        if (hasEmail) {
66	            level++;
67	        }
68	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
69	        if (noNamesakes) {
70	            level++;
71	        }
72	        return Math.min(level, 3);
73	    }
74	
75	    /**
76	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the
77	     * last two digits of the registrationDate year, e.g. {@code 'SMI-0007-M26'}. Returns
78	     * {@code null} when the owner has no customer code or registration date.
79	     */
80	    default String membershipNumber(Owner owner) {
81	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
82	            return null;
83	        }
84	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
85	    }
86	
87	    /**
88	     * Computes the owner's check digit: a single Luhn check digit (0-9) over the digits
89	     * contained in the owner's customerCode. Returns {@code null} when the owner has no
90	     * customer code.
91	     */
92	    default Integer checkDigit(Owner owner) {
93	        if (owner == null || owner.getCustomerCode() == null) {
94	            return null;
95	        }
96	        String code = owner.getCustomerCode();
97	        int sum = 0;
98	        boolean dbl = true;
99	        for (int i = code.length() - 1; i >= 0; i--) {
100	            char c = code.charAt(i);
101	            if (c < '0' || c > '9') {
102	                continue;
103	            }
104	            int d = c - '0';
105	            if (dbl) {
106	                d *= 2;
107	                if (d > 9) {
108	                    d -= 9;
109	                }
110	            }
111	            sum += d;
112	            dbl = !dbl;
113	        }
114	        return (10 - (sum % 10)) % 10;
115	    }
116	
117	    /**
118	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
119	     */
120	    default String displayName(Owner owner) {
121	        if (owner == null) {
122	            return null;
123	        }
124	        return owner.getLastName() + ", " + owner.getFirstName();
125	    }
126	
127	    /**
128	     * Returns the owner's initials as the upper-cased first letters of firstName and
